<?php

require_once 'flatted.php';

function testParse() {
    $json = '[{"a":1,"b":{"$ref":"1"}},{"a":2}]';
    $expected = array("a" => 1, "b" => array("a" => 2));
    $result = Flatted::parse($json, true);
    assert($result == $expected, 'Test parse failed');
}

function testStringify() {
    $value = array("a" => 1, "b" => array("a" => 2));
    $expected = '[{"a":1,"b":{"$ref":"1"}},{"a":2}]';
    $result = Flatted::stringify($value);
    assert($result == $expected, 'Test stringify failed');
}

function runTests() {
    testParse();
    testStringify();
    echo "All tests passed.";
}

runTests();
?>